/* @lc app=leetcode id=3393 lang=kotlin */ class Solution { fun countPathsWithXorValue(grid: Array<IntArray>, k: Int): Int = grid[0].size.let { n -> grid.indices.fold(Array(n) { IntArray(16) }) { prev, i -> Array(n) { IntArray(16) }.also { cur -> (0 until n).forEach { j -> (0 until 16).forEach { y -> cur[j][y] = if (i == 0 && j == 0) (if (y == grid[0][0]) 1 else 0) else (prev[j][y xor grid[i][j]] + (if (j > 0) cur[j - 1][y xor grid[i][j]] else 0)) % 1_000_000_007 } } } }.let { it[n - 1][k] } } }